import java.util.*;

class Solution {
    public boolean isBalanced(TreeNode root) {
        boolean[] ok = new boolean[] { true };
        height(root, ok);
        return ok[0];
    }

    private int height(TreeNode node, boolean[] ok) {
        if (node == null) {
            return 0;
        }
        int left = height(node.left, ok);
        int right = height(node.right, ok);
        if (Math.abs(left - right) > 1) {
            ok[0] = false;
        }
        return 1 + Math.max(left, right);
    }
}
